      "title": "Paparazzi",
      "director": "Jacques Rozier",
      "year": 1964,
      "duration": 18,
      "poster": "https://a.ltrbxd.com/resized/film-poster/1/7/7/8/1/9/177819-paparazzi-0-500-0-750-crop.jpg?v=01602d7ead",
