      "director": "Tiago Guedes",
      "year": 2026,
      "duration": 204,
      "poster": "https://a.ltrbxd.com/resized/film-poster/1/4/2/3/7/6/5/1423765-aqui-3-0-500-0-750-crop.jpg?v=784de7665f",
